var t=[{title:`Pohyby kyčle`,text:`Flexe kyčle přivádí stehno k trupu a extenze ho odvádí dozadu. Kloub se také otáčí dovnitř a ven a pohybuje nohou přes tělo nebo od něj. Každodenní pohyby kombinují několik směrů, takže předklon k špičkám prozradí jen část příběhu.`},{title:`Cviky k vyzkoušení`,text:`Pohodlné protažení flexorů kyčle v polokleku zkoumá extenzi, zatímco udržujete pánev pod kontrolou. Jemné rotace kyčlí 90/90 nebo rotační cviky vsedě procvičují rotaci a podepřený boční výpad zkoumá délku a kontrolu vnitřní strany stehna (adduktorů). Začněte pomalu a držte se opory, pokud je vaše rovnováha vratká.`},{title:`Kyčle ve vašich cvicích`,text:`Dřepy potřebují, aby se kyčle a kotníky pohybovaly společně. Hinge potřebuje flexi kyčle s kontrolovaným trupem. U split dřepu se jedna kyčel natahuje, zatímco druhá ohýbá. Pokud je hluboký dřep nepohodlný, může to rychleji vyřešit jiný postoj, menší hloubka, podložení pat nebo dřep na židli než vynucené protahování.`},{title:`Kyčle má každý jiné`,text:`Tvar kyčelní jamky, tréninková historie, současná síla a snášenlivost kloubů ovlivňují váš rozsah. Asymetrie není automaticky vada a stejné protažení nepatří do každého plánu. Přestaňte s každým cvikem, který způsobuje skřípnutí, ostrou bolest kloubu nebo přetrvávající příznaky, a podle potřeby navštivte lékaře nebo fyzioterapeuta.`},{title:`Sledování pokroku`,text:`Před tréninky, kde pohyb z toho těží, udělejte několik cílených cviků pro kyčle. Pokrok měřte podle toho, jak jistě a plynule působí vaše dřepy, hinge a výpady, a maximální hloubku protažení nechte stranou.`}];var n=[{label:`ACE 2026: mobilita versus flexibilita`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`Knihovna cviků ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Stanovisko ACSM z roku 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var a={sections:t,sources:n};export{a as default,t as sections,n as sources};